     1	#!/bin/sh
     2	set -eu
     3	
     4	skip_initial_refresh=false
     5	wait_for_output=false
     6	case "${1:-}" in
     7	  '')
     8	    ;;
     9	  --skip-initial-refresh)
    10	    skip_initial_refresh=true
    11	    ;;
    12	  --wait-for-output)
    13	    wait_for_output=true
    14	    ;;
    15	  *)
    16	    printf 'usage: labwc-output-watch [--skip-initial-refresh|--wait-for-output]\n' >&2
    17	    exit 2
    18	    ;;
    19	esac
    20	[ "$#" -le 1 ] || {
    21	  printf 'usage: labwc-output-watch [--skip-initial-refresh|--wait-for-output]\n' >&2
    22	  exit 2
    23	}
    24	
    25	if [ -r /etc/default/labwc-desktop ]; then
    26	  # shellcheck disable=SC1091
    27	  . /etc/default/labwc-desktop
    28	fi
    29	
    30	debounce_seconds=${LABWC_OUTPUT_HOTPLUG_DEBOUNCE_SECONDS:-2}
    31	case "$debounce_seconds" in
    32	  ''|*[!0-9]*)
    33	    debounce_seconds=2
    34	    ;;
    35	esac
    36	if [ "$debounce_seconds" -gt 30 ]; then
    37	  debounce_seconds=2
    38	fi
    39	
    40	output_refresh=$(command -v labwc-output-refresh || true)
    41	[ -n "$output_refresh" ] || exit 0
    42	
    43	wait_for_wayland_output() {
    44	  wlr_randr=$(command -v wlr-randr || true)
    45	  [ -n "$wlr_randr" ] || exit 1
    46	
    47	  output_attempt=1
    48	  while [ "$output_attempt" -le 100 ]; do
    49	    output_snapshot=$(
    50	      /usr/bin/timeout 2 "$wlr_randr" 2>/dev/null || true
    51	    )
    52	    [ -n "$output_snapshot" ] && return 0
    53	    sleep 0.1
    54	    output_attempt=$((output_attempt + 1))
    55	  done
    56	
    57	  printf 'fatal: Labwc did not expose a usable Wayland output within 10 seconds\n' >&2
    58	  exit 1
    59	}
    60	
    61	apply_output_policy() {
    62	  if "$output_refresh" --idle-topology-active; then
    63	    "$output_refresh" --restore-idle-topology >/dev/null 2>&1 || true
    64	    return 0
    65	  fi
    66	  "$output_refresh" || true
    67	}
    68	
    69	pending_refresh_pid=
    70	monitor_pid=
    71	watch_dir=
    72	event_fifo=
    73	
    74	cancel_pending_refresh() {
    75	  [ -n "$pending_refresh_pid" ] || return 0
    76	  kill "$pending_refresh_pid" >/dev/null 2>&1 || true
    77	  wait "$pending_refresh_pid" 2>/dev/null || true
    78	  pending_refresh_pid=
    79	}
    80	
    81	schedule_output_policy() {
    82	  cancel_pending_refresh
    83	  (
    84	    sleep "$debounce_seconds"
    85	    udevadm settle --timeout=5 >/dev/null 2>&1 || true
    86	    apply_output_policy
    87	  ) </dev/null &
    88	  pending_refresh_pid=$!
    89	}
    90	
    91	cleanup_output_watch() {
    92	  cancel_pending_refresh
    93	  if [ -n "$monitor_pid" ]; then
    94	    kill "$monitor_pid" >/dev/null 2>&1 || true
    95	    wait "$monitor_pid" 2>/dev/null || true
    96	    monitor_pid=
    97	  fi
    98	  [ -z "$event_fifo" ] || rm -f -- "$event_fifo"
    99	  [ -z "$watch_dir" ] || rmdir -- "$watch_dir" 2>/dev/null || true
   100	}
   101	
   102	trap cleanup_output_watch EXIT
   103	trap 'exit 0' HUP INT TERM
   104	
   105	if [ "$wait_for_output" = true ]; then
   106	  wait_for_wayland_output
   107	  exit 0
   108	fi
   109	
   110	if [ "$skip_initial_refresh" != true ]; then
   111	  apply_output_policy
   112	fi
   113	
   114	command -v udevadm >/dev/null 2>&1 || exit 0
   115	command -v mkfifo >/dev/null 2>&1 || exit 0
   116	command -v mktemp >/dev/null 2>&1 || exit 0
   117	
   118	runtime_root=${XDG_RUNTIME_DIR:-${TMPDIR:-/tmp}}
   119	case "$runtime_root" in
   120	  /*) ;;
   121	  *) runtime_root=/tmp ;;
   122	esac
   123	if [ ! -d "$runtime_root" ] || [ ! -w "$runtime_root" ]; then
   124	  runtime_root=/tmp
   125	fi
   126	
   127	umask 077
   128	watch_dir=$(mktemp -d "${runtime_root%/}/labwc-output-watch.XXXXXX") || exit 0
   129	event_fifo="${watch_dir}/events"
   130	mkfifo "$event_fifo" || exit 0
   131	
   132	udevadm monitor --subsystem-match=drm >"$event_fifo" 2>/dev/null &
   133	monitor_pid=$!
   134	
   135	while IFS= read -r event_line; do
   136	  case "$event_line" in
   137	    *' change '*|*' add '*|*' remove '*|*change*drm*|*add*drm*|*remove*drm*)
   138	      schedule_output_policy
   139	      ;;
   140	  esac
   141	done <"$event_fifo"
   142	
   143	if [ -n "$pending_refresh_pid" ]; then
   144	  wait "$pending_refresh_pid" 2>/dev/null || true
   145	  pending_refresh_pid=
   146	fi
   147	wait "$monitor_pid" 2>/dev/null || true
   148	monitor_pid=

