   596	sub run_optional {
   597	    my ($command_name, @args) = @_;
   598	    my $command = find_command($command_name);
   599	    return 0 if !defined $command;
   600	    system {$command} $command, @args;
   601	    return $? == 0 ? 1 : 0;
   602	}
   603	
   604	sub connected_outputs {
   605	    my (@state_lines) = @_;
   606	    my @names;
   607	
   608	    for my $line (@state_lines) {
   609	        next if $line =~ /^\s*$/ || $line =~ /^[[:space:]]/;
   610	        my ($output_name) = split /[[:space:]]+/, $line, 2;
   611	        next if !output_name_safe($output_name);
   612	        push @names, $output_name;
   613	    }
   614	    return @names;
   615	}
   616	
   617	sub output_name_safe {
   618	    my ($output_name) = @_;
   619	    return defined $output_name && $output_name =~ /\A[A-Za-z0-9._-]+\z/;
   620	}
   621	
   622	sub is_internal_output {
   623	    my ($output_name) = @_;
   624	    my @prefixes = split /[[:space:]]+/, ($defaults{LABWC_OUTPUT_INTERNAL_PREFIXES} // 'eDP LVDS DSI');
   625	    for my $prefix (@prefixes) {
   626	        next if $prefix eq q{};
   627	        return 1 if $output_name =~ /\A\Q$prefix\E(?:-|[0-9])/;
   628	    }
   629	    return 0;
   630	}
   631	
   632	sub is_hdmi_output {
   633	    my ($output_name) = @_;
   634	    return defined $output_name && $output_name =~ /\AHDMI(?:-|[0-9])/;
   635	}
   636	
   637	sub output_modes {
   638	    my ($state_lines, $output_name) = @_;
   639	    my @modes;
   640	    my $in_output = 0;
   641	
   642	    for my $line (@{$state_lines}) {
   643	        if ($line =~ /^\Q$output_name\E\b/) {
   644	            $in_output = 1;
   645	            next;
   646	        }
   647	        if ($line !~ /^[[:space:]]/ && $in_output) {
   648	            last;
   649	        }
   650	        next if !$in_output;
   651	        next if $line !~ /^\s+(\d+)x(\d+)\s+px,\s+([0-9.]+)\s+Hz\b(.*)$/;
   652	
   653	        my ($width, $height, $hz, $flags) = ($1, $2, $3, $4 // q{});
   654	        my $size = "${width}x${height}";
   655	        push @modes, {
   656	            area       => $width * $height,
   657	            flags      => $flags,
   658	            hz         => $hz + 0,
   659	            preferred  => ($flags =~ /preferred/) ? 1 : 0,
   660	            rounded_hz => int(($hz + 0) + 0.5),
   661	            size       => $size,
   662	            value      => sprintf('%s@%sHz', $size, $hz),
   663	        };
   664	    }
   665	
   666	    return @modes;
   667	}
   668	
   669	sub mode_for_output {
   670	    my ($state_lines, $output_name) = @_;
   671	    my @modes = output_modes($state_lines, $output_name);
   672	    return undef if !@modes;
   673	
   674	    my $output_class = is_internal_output($output_name) ? 'INTERNAL' : 'EXTERNAL';
   675	    my $preferred_width =
   676	      optional_uint($defaults{"LABWC_OUTPUT_${output_class}_PREFERRED_WIDTH"});
   677	    my $preferred_height =
   678	      optional_uint($defaults{"LABWC_OUTPUT_${output_class}_PREFERRED_HEIGHT"});
   679	    my $preferred_hz =
   680	      optional_uint($defaults{"LABWC_OUTPUT_${output_class}_PREFERRED_REFRESH_HZ"});
   681	    my $fallback_hz      = optional_uint($defaults{LABWC_OUTPUT_FALLBACK_REFRESH_HZ});
   682	
   683	    if (defined $preferred_width && defined $preferred_height) {
   684	        my $preferred_size = "${preferred_width}x${preferred_height}";
   685	        my @size_matches = grep { $_->{size} eq $preferred_size } @modes;
   686	        if (@size_matches) {
   687	            if (defined $preferred_hz) {
   688	                my ($exact_mode) = grep { $_->{rounded_hz} == $preferred_hz } @size_matches;
   689	                return $exact_mode->{value} if defined $exact_mode;
   690	            }
   691	
   692	            my ($preferred_mode) = grep { $_->{preferred} } @size_matches;
   693	            return $preferred_mode->{value} if defined $preferred_mode;
   694	
   695	            my $fallback_mode = best_mode(\@size_matches, $fallback_hz);
   696	            return $fallback_mode->{value} if defined $fallback_mode;
   697	        }
   698	    }
   699	
   700	    my ($connector_preferred_mode) = grep { $_->{preferred} } @modes;
   701	    if (defined $connector_preferred_mode) {
   702	        return $connector_preferred_mode->{value}
   703	          if !defined($fallback_hz) || $connector_preferred_mode->{rounded_hz} >= $fallback_hz;
   704	    }
   705	
   706	    if (defined $fallback_hz) {
   707	        my @refresh_capable_modes = grep { $_->{rounded_hz} >= $fallback_hz } @modes;
   708	        if (@refresh_capable_modes) {
   709	            my $largest_refresh_capable_area = 0;
   710	            for my $mode (@refresh_capable_modes) {
   711	                $largest_refresh_capable_area = $mode->{area}
   712	                  if $mode->{area} > $largest_refresh_capable_area;
   713	            }
   714	            my @largest_refresh_capable_modes = grep {
   715	                $_->{area} == $largest_refresh_capable_area
   716	            } @refresh_capable_modes;
   717	            my $refresh_capable_mode = best_mode(\@largest_refresh_capable_modes, $fallback_hz);
   718	            return $refresh_capable_mode->{value} if defined $refresh_capable_mode;
   719	        }
   720	    }
   721	
   722	    my $largest_area = 0;
   723	    for my $mode (@modes) {
   724	        $largest_area = $mode->{area} if $mode->{area} > $largest_area;
   725	    }
   726	    my @largest_modes = grep { $_->{area} == $largest_area } @modes;
   727	    my $largest_mode = best_mode(\@largest_modes, $fallback_hz);
   728	    return $largest_mode->{value} if defined $largest_mode;
   729	
   730	    return undef;
   731	}
   732	
   733	sub logical_width_for_output {
   734	    my ($output_mode, $output_name) = @_;
   735	    return 0 if !defined $output_mode || $output_mode !~ /\A(\d+)x\d+@/;
   736	
   737	    my $physical_width = int($1);
   738	    my $output_scale = scale_for_output($output_name);
   739	    return int(($physical_width / $output_scale) + 0.5);
   740	}
   741	
   742	sub optional_uint {
   743	    my ($value) = @_;
   744	    return undef if !defined $value || $value eq q{} || $value !~ /\A\d+\z/;
   745	    return int($value);
   746	}
   747	
   748	sub best_mode {
   749	    my ($modes, $preferred_hz) = @_;
   750	    return undef if !@{$modes};
   751	
   752	    my @sorted = sort {
   753	        mode_sort_key($a, $preferred_hz) <=> mode_sort_key($b, $preferred_hz)
   754	          ||
   755	        $b->{hz} <=> $a->{hz}
   756	    } @{$modes};
   757	
   758	    return $sorted[0];
   759	}
   760	
   761	sub mode_sort_key {
   762	    my ($mode, $preferred_hz) = @_;
   763	    return 0 if !defined $preferred_hz;
   764	    return abs($mode->{rounded_hz} - $preferred_hz);
   765	}
   766	
   767	sub scale_for_output {
   768	    my ($output_name) = @_;
   769	    my $scale_value;
   770	
   771	    if (is_internal_output($output_name)) {
   772	        $scale_value = $defaults{LABWC_OUTPUT_INTERNAL_SCALE} // $defaults{LABWC_OUTPUT_SCALE} // '1';
   773	    } else {
   774	        $scale_value = $defaults{LABWC_OUTPUT_EXTERNAL_SCALE} // $defaults{LABWC_OUTPUT_SCALE} // '1';
   775	    }
   776	
   777	    return '1'
   778	      if $scale_value !~ /\A\d+(?:\.\d+)?\z/
   779	      || $scale_value < 0.5
   780	      || $scale_value > 3;
   781	    return $scale_value;
   782	}
   783	
   784	sub enable_output {
   785	    my ($wlr_randr, $output_name, $output_mode, $output_position) = @_;
   786	    return 0 if !output_name_safe($output_name);
   787	    return 0
   788	      if !defined $output_position
   789	      || $output_position !~ /\A-?\d+,-?\d+\z/;
   790	
   791	    my $output_scale = scale_for_output($output_name);
   792	    my @base_args =
   793	      ('--output', $output_name, '--on', '--scale', $output_scale, '--pos', $output_position);
   794	
   795	    if (defined $output_mode && $output_mode ne q{}) {
   796	        system {$wlr_randr} $wlr_randr, @base_args[0 .. 2], '--mode', $output_mode, @base_args[3 .. $#base_args];
   797	        return 1 if $? == 0;
   798	    }
   799	
   800	    system {$wlr_randr} $wlr_randr, @base_args;
   801	    return $? == 0 ? 1 : 0;
   802	}
   803	
   804	sub disable_output {
   805	    my ($wlr_randr, $output_name) = @_;
   806	    return if !output_name_safe($output_name);
   807	    system {$wlr_randr} $wlr_randr, '--output', $output_name, '--off';
   808	    return;
   809	}
   810	
   811	sub topology_changed {
   812	    my ($state_before, $state_after) = @_;
   813	    return 0 if $state_before eq q{} || $state_after eq q{};
   814	    return normalized_state($state_before) ne normalized_state($state_after) ? 1 : 0;
   815	}
   816	
   817	sub normalized_state {
   818	    my ($state) = @_;
   819	    my @lines = map {
   820	        my $line = $_;
   821	        $line =~ s/\s+$//;
   822	        $line;
   823	    } split /\n/, $state;
   824	    return join "\n", @lines;
   825	}
   826	
   827	sub refresh_output_chrome {
   828	    my ($delay_us) = @_;
   829	    return if !session_is_wayland_active();
   830	    $delay_us = 300_000 if !defined $delay_us || $delay_us !~ /\A\d+\z/;
   831	    usleep($delay_us);
   832	    # Systemd owns these chrome PIDs and serializes each replacement, so this
   833	    # helper never needs to signal a compositor or application process.
   834	    refresh_waybar();
   835	    refresh_dock();
   836	    return;
   837	}
   838	
   839	sub refresh_output_chrome_after_dpms {
   840	    return if !session_is_wayland_active();
   841	    usleep(300_000);
   842	    refresh_waybar();
   843	    return;
   844	}
   845	
   846	sub topology_restart_delay_us {
   847	    my ($selected_output, @outputs_to_disable) = @_;
   848	    my $delay_us = 300_000;
   849	
   850	    return $delay_us if !defined $selected_output || !is_internal_output($selected_output);
   851	    return $delay_us if !grep { !is_internal_output($_) } @outputs_to_disable;
   852	
   853	    my $extra_delay_seconds = optional_uint($defaults{LABWC_OUTPUT_INTERNAL_REFRESH_DELAY_SECONDS});
   854	    $extra_delay_seconds = 1 if !defined $extra_delay_seconds;
   855	    return $delay_us + ($extra_delay_seconds * 1_000_000);
   856	}
   857	
   858	sub session_is_wayland_active {
   859	    return 1 if defined $ENV{WAYLAND_DISPLAY} && $ENV{WAYLAND_DISPLAY} ne q{};
   860	    return 1 if defined $ENV{SWAYSOCK} && $ENV{SWAYSOCK} ne q{};
   861	    return (($ENV{XDG_SESSION_TYPE} // q{}) eq 'wayland') ? 1 : 0;
   862	}
   863	
   864	sub enabled_setting {
   865	    my ($value) = @_;
   866	    return 1 if !defined $value;
   867	    return $value =~ /\A(?:true|yes|1|on)\z/i ? 1 : 0;
   868	}
   869	
   870	sub refresh_waybar {
   871	    return if !enabled_setting($defaults{LABWC_ENABLE_WAYBAR});
   872	
   873	    my $systemctl = find_command('systemctl');
   874	    return if !defined $systemctl;
   875	
   876	    system {$systemctl} $systemctl, '--user', '--quiet', 'is-active', 'waybar.service';
   877	    if ($? == 0) {
   878	        system {$systemctl} $systemctl, '--user', '--no-block', 'restart', 'waybar.service';
   879	        return;
   880	    }
   881	
   882	    system {$systemctl} $systemctl, '--user', '--no-block', 'start', 'waybar.service';
   883	    return;
   884	}
   885	
   886	sub refresh_dock {
   887	    return if !enabled_setting($defaults{LABWC_ENABLE_CRYSTAL_DOCK});
   888	
   889	    my $systemctl = find_command('systemctl');
   890	    return if !defined $systemctl;
   891	
   892	    # Output handling is deliberately limited to these independent chrome
   893	    # units. It never stops the Labwc session or terminates application PIDs.
   894	    system {$systemctl} $systemctl, '--user', '--no-block', 'restart',
   895	      'crystal-dock.service';
   896	    return;
   897	}

