     1	package AppArmor::ManagedModes::Verify;
     2	
     3	use strict;
     4	use warnings;
     5	
     6	use Exporter qw(import);
     7	use Moo;
     8	use MooX::StrictConstructor;
     9	use MooX::TypeTiny;
    10	
    11	use AppArmor::ManagedModes::CLI qw(fatal info);
    12	use AppArmor::ManagedModes::Config qw(limits);
    13	use AppArmor::ManagedModes::LoadedState qw(
    14	    contains_exact_line
    15	    contains_label_prefix
    16	    read_snapshot
    17	);
    18	use AppArmor::ManagedModes::Transition qw(profile_mode_matches);
    19	use AppArmor::ManagedModes::TrustedPath qw(
    20	    bounded_capture
    21	    file_size
    22	);
    23	
    24	our @EXPORT_OK = qw(
    25	    verify_loaded_profile_modes
    26	    verify_source_profile_modes
    27	);
    28	
    29	sub verify_source_profile_modes {
    30	    my ($entries, $profile_dir) = @_;
    31	
    32	    for my $entry (@$entries) {
    33	        profile_mode_matches(
    34	            $entry->{mode},
    35	            $entry->{name},
    36	            $entry->{path},
    37	            $profile_dir,
    38	        ) || fatal(
    39	            'AppArmor profile source mode mismatch: '
    40	            . "$entry->{name} expected=$entry->{mode}"
    41	        );
    42	    }
    43	}
    44	
    45	sub verify_loaded_profile_modes {
    46	    my ($entries, $options, $workspace, $tools) = @_;
    47	    my $limits = limits();
    48	    my $parser_path = "$options->{tool_dir}/apparmor_parser";
    49	    $tools->require_executable('required AppArmor parser', $parser_path);
    50	
    51	    my ($loaded_fh, $loaded_snapshot_path) =
    52	        $workspace->tempfile(
    53	            'apparmor-loaded-profiles',
    54	            'cannot create loaded profile snapshot',
    55	        );
    56	    close $loaded_fh || fatal('cannot create loaded profile snapshot');
    57	    my ($names_fh, $profile_names_path) =
    58	        $workspace->tempfile(
    59	            'apparmor-profile-names',
    60	            'cannot create profile name snapshot',
    61	        );
    62	    close $names_fh || fatal('cannot create profile name snapshot');
    63	
    64	    bounded_capture(
    65	        'loaded AppArmor profile state',
    66	        $options->{loaded_profiles_path},
    67	        $loaded_snapshot_path,
    68	        $limits->{max_loaded_profiles_bytes},
    69	    );
    70	    my $loaded_state = read_snapshot($loaded_snapshot_path);
    71	
    72	    for my $entry (@$entries) {
    73	        my $parse_path = $entry->{path};
    74	        my $base_dir = $options->{profile_dir};
    75	        my $label_work_dir;
    76	
    77	        if ($entry->{mode} eq 'disable') {
    78	            $label_work_dir = $workspace->tempdir(
    79	                'apparmor-profile-names',
    80	                'cannot create isolated AppArmor label workspace',
    81	            );
    82	            $parse_path = "$label_work_dir/$entry->{name}";
    83	            $base_dir = $label_work_dir;
    84	            $workspace->copy_file(
    85	                $entry->{path},
    86	                $parse_path,
    87	                "cannot stage AppArmor profile for label derivation: $entry->{name}",
    88	            );
    89	        }
    90	
    91	        $workspace->truncate_file($profile_names_path);
    92	        $tools->run_stdout_to_file_limited_or_exit(
    93	            $profile_names_path,
    94	            $limits->{max_profile_names_bytes},
    95	            'AppArmor profile labels exceed '
    96	                . "$limits->{max_profile_names_bytes} bytes: $entry->{name}",
    97	            $parser_path,
    98	            '-q',
    99	            '-N',
   100	            '-Q',
   101	            '-K',
   102	            '-T',
   103	            '-I',
   104	            $options->{profile_dir},
   105	            '--base',
   106	            $base_dir,
   107	            $parse_path,
   108	        );
   109	        if (defined $label_work_dir) {
   110	            $workspace->remove_dir($label_work_dir);
   111	        }
   112	
   113	        my $profile_names_size = file_size($profile_names_path);
   114	        $profile_names_size > 0 ||
   115	            fatal("AppArmor profile defines no labels: $entry->{name}");
   116	        $profile_names_size <= $limits->{max_profile_names_bytes} ||
   117	            fatal(
   118	                'AppArmor profile labels exceed '
   119	                . "$limits->{max_profile_names_bytes} bytes: $entry->{name}"
   120	            );
   121	
   122	        open my $labels_fh, '<:raw', $profile_names_path ||
   123	            fatal("cannot derive AppArmor profile labels: $entry->{name}");
   124	        while (my $profile_label = <$labels_fh>) {
   125	            $profile_label =~ s/\n\z//;
   126	            $profile_label ne '' ||
   127	                fatal("AppArmor parser returned an empty label: $entry->{name}");
   128	            length($profile_label) <= $limits->{max_line_bytes} ||
   129	                fatal(
   130	                    'AppArmor profile label exceeds '
   131	                    . "$limits->{max_line_bytes} bytes: $entry->{name}"
   132	                );
   133	
   134	            if ($entry->{mode} eq 'disable') {
   135	                !contains_label_prefix($loaded_state, $profile_label) ||
   136	                    fatal("disabled AppArmor profile remains loaded: $profile_label");
   137	            }
   138	            elsif (index($profile_label, '//') >= 0) {
   139	                contains_exact_line(
   140	                    $loaded_state,
   141	                    "$profile_label (enforce)",
   142	                ) || contains_exact_line(
   143	                    $loaded_state,
   144	                    "$profile_label (complain)",
   145	                ) || fatal(
   146	                    'AppArmor child profile is not loaded in a confined mode: '
   147	                    . $profile_label
   148	                );
   149	            }
   150	            else {
   151	                contains_exact_line(
   152	                    $loaded_state,
   153	                    "$profile_label ($entry->{mode})",
   154	                ) || fatal(
   155	                    "AppArmor profile is not loaded in $entry->{mode} mode: "
   156	                    . $profile_label
   157	                );
   158	            }
   159	        }
   160	        close $labels_fh ||
   161	            fatal("cannot derive AppArmor profile labels: $entry->{name}");
   162	    }
   163	
   164	    info('loaded profile modes verified');
   165	}
   166	
   167	1;
--- loaded state semantics ---
     1	package AppArmor::ManagedModes::LoadedState;
     2	
     3	use strict;
     4	use warnings;
     5	
     6	use Exporter qw(import);
     7	use Moo;
     8	use MooX::StrictConstructor;
     9	use MooX::TypeTiny;
    10	
    11	use AppArmor::ManagedModes::CLI qw(fatal);
    12	
    13	our @EXPORT_OK = qw(
    14	    contains_exact_line
    15	    contains_label_prefix
    16	    read_snapshot
    17	);
    18	
    19	sub read_snapshot {
    20	    my ($path) = @_;
    21	
    22	    open my $fh, '<:raw', $path ||
    23	        fatal("cannot read loaded AppArmor profile state: $path");
    24	    local $/;
    25	    my $content = <$fh>;
    26	    close $fh ||
    27	        fatal("cannot read loaded AppArmor profile state: $path");
    28	    return defined($content) ? $content : '';
    29	}
    30	
    31	sub contains_label_prefix {
    32	    my ($snapshot, $label) = @_;
    33	
    34	    return index($snapshot, "$label (") == 0 ||
    35	        index($snapshot, "\n$label (") >= 0;
    36	}
    37	
    38	sub contains_exact_line {
    39	    my ($snapshot, $line) = @_;
    40	
    41	    for my $candidate (split(/\n/, $snapshot, -1)) {
    42	        return 1 if $candidate eq $line;
    43	    }
    44	    return 0;
    45	}
    46	
    47	1;


