   810	apparmor_apply_desktop_state() {
   811	  mode_config=$1
   812	
   813	  [ "${DESKTOP_APPARMOR_STATE+x}" = x ] || return 0
   814	  desktop_apparmor_state=$(apparmor_requested_desktop_state) || return 1
   815	  desktop_apparmor_profiles=$(apparmor_desktop_state_profile_files)
   816	  desktop_apparmor_tmp="${mode_config}.desktop-state.$$"
   817	
   818	  awk \
   819	    -v selected_state="$desktop_apparmor_state" \
   820	    -v selected_profiles="$desktop_apparmor_profiles" '
   821	      BEGIN {
   822	        profile_count = split(selected_profiles, profile_names, "\n")
   823	        for (profile_index = 1; profile_index <= profile_count; profile_index++) {
   824	          if (profile_names[profile_index] != "") {
   825	            managed[profile_names[profile_index]] = 1
   826	          }
   827	        }
   828	      }
   829	      /^[[:space:]]*(#|$)/ {
   830	        print
   831	        next
   832	      }
   833	      $3 in managed {
   834	        if (NF != 4) {
   835	          exit 40
   836	        }
   837	        seen[$3]++
   838	        $1 = selected_state
   839	        print
   840	        next
   841	      }
   842	      {
   843	        print
   844	      }
   845	      END {
   846	        for (profile_name in managed) {
   847	          if (seen[profile_name] != 1) {
   848	            exit 41
   849	          }
   850	        }
   851	      }
